CREATE TABLE ${1:dbo}.${2:table_name} (
  ${3:id} INT IDENTITY(1,1) PRIMARY KEY,
  ${4:name} NVARCHAR(${5:255}) NOT NULL,
  created_at DATETIME2 NOT NULL CONSTRAINT DF_${2}_created_at DEFAULT SYSUTCDATETIME()
);

CREATE NONCLUSTERED INDEX ${1:IX_${2:table_name}_${3:column_name}}
  ON ${4:dbo}.${2} (${3})
  INCLUDE (${5:other_column});

CREATE OR ALTER VIEW ${1:dbo}.${2:view_name}
AS
SELECT
  ${3:column_list}
FROM ${4:dbo}.${5:source_table}
WHERE ${6:condition};

SELECT TOP ${1:100} ${2:*}
FROM ${3:dbo}.${4:table_name}
WHERE ${5:condition}
ORDER BY ${6:column} ${7:DESC};

INSERT INTO ${1:dbo}.${2:target_table} (${3:col_a}, ${4:col_b})
SELECT ${3}, ${4}
FROM ${5:dbo}.${6:source_table}
WHERE ${7:condition};

UPDATE t
  SET t.${1:target_col} = s.${2:source_col}
FROM ${3:dbo}.${4:target_table} AS t
INNER JOIN ${5:dbo}.${6:source_table} AS s
  ON s.${7:key} = t.${7}
WHERE ${8:condition};

MERGE ${1:dbo}.${2:target_table} AS t
USING (
  SELECT ${3:key_value} AS ${4:key_col}, ${5:new_value} AS ${6:val_col}
) AS s
ON t.${4} = s.${4}
WHEN MATCHED THEN
  UPDATE SET t.${6} = s.${6}
WHEN NOT MATCHED THEN
  INSERT (${4}, ${6})
  VALUES (s.${4}, s.${6});

WITH ranked AS (
  SELECT
    ${1:*},
    ROW_NUMBER() OVER (
      PARTITION BY ${2:partition_col}
      ORDER BY ${3:order_col} ${4:DESC}
    ) AS rn
  FROM ${5:dbo}.${6:table_name}
)
SELECT *
FROM ranked
WHERE rn <= ${7:1};

SELECT ${1:key_col}, ${2:[A], [B], [C]}
FROM (
  SELECT ${1}, ${3:pivot_col}, ${4:value_col}
  FROM ${5:dbo}.${6:table_name}
) AS src
PIVOT (
  ${7:SUM}(${4}) FOR ${3} IN (${2})
) AS p;

SELECT ${1:key_col}, ${2:attr}, ${3:value}
FROM (
  SELECT ${1}, ${4:col_a}, ${5:col_b}, ${6:col_c}
  FROM ${7:dbo}.${8:table_name}
) AS src
UNPIVOT (
  ${3} FOR ${2} IN (${4}, ${5}, ${6})
) AS u;

WITH ${1:cte_name} AS (
  SELECT ${2:column_list}
  FROM ${3:dbo}.${4:source_table}
  WHERE ${5:condition}
)
SELECT *
FROM ${1};

RESTORE DATABASE [${1:database_name}]
  FROM DISK = N'${2:C:\Backups\${1}_full.bak}'
  WITH REPLACE, RECOVERY, STATS = 10;
